package net.civeira.phylax.feature.observe.observedfingerprintrule.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRule;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.valueobject.UidVO;

class UidValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of uid of observed fingerprint rule")
  void test_uid_value_holder_assign_plain_value() {
    Object holder = new Object();
    UidValueHolder<Object> value = new UidValueHolder<>(holder);
    Assertions.assertSame(holder, value.uid("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getUidValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getUid().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of uid of observed fingerprint rule")
  void test_uid_value_holder_assign_value_object() {
    Object holder = new Object();
    UidValueHolder<Object> value = new UidValueHolder<>(holder);
    UidVO vo = UidVO.from("one");
    Assertions.assertFalse(value.getUidValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.uid(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getUidValue().orElseThrow());
    Assertions.assertSame(holder, value.uid(Optional.empty()));
    Assertions.assertFalse(value.getUidValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.uid(Optional.of(vo)));
    Assertions.assertSame(vo, value.getUidValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of uid of observed fingerprint rule against the original")
  void test_uid_value_holder_read() {
    Object holder = new Object();
    UidValueHolder<Object> value = new UidValueHolder<>(holder);
    UidVO vo = UidVO.from("one");
    UidVO other = UidVO.from("one");
    ObservedFingerprintRule original = Mockito.mock(ObservedFingerprintRule.class);
    Mockito.when(original.getUidValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readUid(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readUid(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.uid(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readUid(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readUid(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of uid of observed fingerprint rule")
  void test_uid_value_holder_unset() {
    Object holder = new Object();
    UidValueHolder<Object> value = new UidValueHolder<>(holder);
    UidVO vo = UidVO.from("one");
    value.uid(vo);
    Assertions.assertSame(holder, value.unsetUidIfMatches("uid_other"));
    Assertions.assertTrue(value.getUidValue().isPresent(), "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetUidIfMatches("uid"));
    Assertions.assertFalse(value.getUidValue().isPresent(), "The field name must clear the value");
    value.uid(vo);
    Assertions.assertSame(holder, value.unsetUid());
    Assertions.assertFalse(value.getUidValue().isPresent(), "Unset must clear the value");
  }
}
